return {api_version=1,id="OG_198",name="Forbidden Healing",text="Spend all your Mana. Restore twice that much Health.",set="OG",type="spell",class="paladin",rarity="epic",spell_school="holy",cost=0,target_mode="required",targets=function(ctx) return ctx:characters() end,on_play=function(ctx,self,target)local p=ctx:controller(self);local amount=ctx:player(p).mana;ctx:spend_mana(p,amount);cardlib.effects.heal(ctx, target,amount*2)end}
